 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */
import React, { useEffect } from 'react';
import { useIntl } from 'react-intl';
import { useLocation } from 'react-router-dom';

// Components
import { Box, Stack, Link, Text, Spinner } from '@salesforce/retail-react-app/app/components/shared/ui';

// Project Components
import Seo from '@salesforce/retail-react-app/app/components/seo';
import Section from '@salesforce/retail-react-app/app/components/section';
import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';

// Hooks
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import { useContentfulEntries, useContentfulEntry } from '../../hooks/useContentful';
import { useContentfulLiveUpdates } from '@contentful/live-preview/react';

// Constants
import {
  HOME_SHOP_PRODUCTS_CATEGORY_ID,
  HOME_SHOP_PRODUCTS_LIMIT,
  MAX_CACHE_AGE,
  STALE_WHILE_REVALIDATE,
} from '../../constants';

import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import { useProductSearch } from '@salesforce/commerce-sdk-react';

// Types
import type { HomepageEntry, AnyContentfulEntry } from '../../types/contentful';

// --- Shared layout ---

const HomepageContent = () => {
  const intl = useIntl();

  const { data: productSearchResult, isLoading: productsLoading } = useProductSearch({
    parameters: {
      refine: [`cgid=${HOME_SHOP_PRODUCTS_CATEGORY_ID as string}`, 'htype=master'] as unknown as string, // SDK types refine as string but runtime accepts string[]
      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
      perPricebook: true,
      allVariationProperties: true,
      limit: HOME_SHOP_PRODUCTS_LIMIT,
    },
  });

  return (
    <>
      {productSearchResult && (
        // From PWA template - Example on how to show products
        <Section
          padding={4}
          paddingTop={16}
          title={intl.formatMessage({
            defaultMessage: 'Shop Products',
            id: 'home.heading.shop_products',
          })}
          subtitle={intl.formatMessage(
            {
              defaultMessage: 'This section contains content from the catalog. {docLink} on how to replace it.',
              id: 'home.description.shop_products',
              description:
                '{docLink} is a html button that links the user to https://sfdc.co/business-manager-manage-catalogs',
            },
            {
              docLink: (
                <Link
                  target="_blank"
                  href={'https://sfdc.co/business-manager-manage-catalogs'}
                  textDecoration={'none'}
                  position={'relative'}
                  _after={{
                    position: 'absolute',
                    content: `""`,
                    height: '2px',
                    bottom: '-2px',
                    margin: '0 auto',
                    left: 0,
                    right: 0,
                    background: 'gray.700',
                  }}
                  _hover={{ textDecoration: 'none' }}
                >
                  {intl.formatMessage({
                    defaultMessage: 'Read docs',
                    id: 'home.link.read_docs',
                  })}
                </Link>
              ),
            },
          )}
        >
          <Stack pt={8} spacing={16}>
            <ProductScroller products={productSearchResult?.hits} isLoading={productsLoading} />
          </Stack>
        </Section>
      )}
    </>
  );
};

// --- Normal (published) home ---

const HomeNormal = () => {
  const einstein = useEinstein();
  const { pathname } = useLocation();

  const { res } = useServerContext();
  if (res) {
    res.set(
      'Cache-Control',
      `s-maxage=${MAX_CACHE_AGE as number}, stale-while-revalidate=${STALE_WHILE_REVALIDATE as number}`,
    );
  }

  const { data: contentfulData, isLoading: contentfulLoading } = useContentfulEntries<HomepageEntry>('homepage');
  const homepageContent = useContentfulLiveUpdates(contentfulData?.[0] ?? null);

  useEffect(() => {
    einstein.sendViewPage(pathname);
  }, []);

  if (contentfulLoading) {
    return (
      <Box display="flex" justifyContent="center" py={16}>
        <Spinner size="xl" />
      </Box>
    );
  }

  if (!homepageContent) return null;

  return <HomepageContent />;
};

// --- Preview (draft) home ---

type HomePreviewContentProps = {
  entryId: string;
};

const HomePreviewContent = ({ entryId }: HomePreviewContentProps) => {
  const { data, isLoading, error } = useContentfulEntry<AnyContentfulEntry>(entryId, true);
  const liveData = useContentfulLiveUpdates(data);

  if (isLoading) {
    return (
      <Box display="flex" justifyContent="center" py={16}>
        <Spinner size="xl" />
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={8}>
        <Text color="red.500">Error loading preview: {error.message}</Text>
      </Box>
    );
  }

  if (!liveData) return null;

  const contentTypeId = liveData.sys?.contentType?.sys?.id;

  if (contentTypeId !== 'homepage') {
    return (
      <Box p={8}>
        <Text>Preview for content type &ldquo;{contentTypeId}&rdquo; is not yet configured.</Text>
      </Box>
    );
  }

  return <HomepageContent />;
};

// --- Page ---

const Home = () => {
  const { search } = useLocation();
  const entryId = new URLSearchParams(search).get('entry');

  return (
    <Box data-testid="home-page">
      <Seo
        title="Home Page"
        description="Commerce Cloud Retail React App"
        keywords="Commerce Cloud, Retail React App, React Storefront"
      />
      {entryId ? <HomePreviewContent entryId={entryId} /> : <HomeNormal />}
    </Box>
  );
};

Home.getTemplateName = () => 'home';

export default Home;

/*
 * Copyright (c) 2021, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */
import React from 'react'
import PropTypes from 'prop-types'
import Helmet from 'react-helmet'

import {DEFAULT_SITE_TITLE} from '@salesforce/retail-react-app/app/constants'

const Seo = ({title, description, noIndex, keywords, children, ...props}) => {
    const fullTitle = title ? `${title} | ${DEFAULT_SITE_TITLE}` : DEFAULT_SITE_TITLE

    return (
        <Helmet {...props}>
            <title>{fullTitle}</title>
            {description && <meta name="description" content={description} />}
            {noIndex && <meta name="robots" content="noindex" />}
            {keywords && <meta name="keywords" content={keywords} />}
            {children}
        </Helmet>
    )
}

Seo.propTypes = {
    title: PropTypes.string,
    description: PropTypes.string,
    noIndex: PropTypes.bool,
    children: PropTypes.node,
    keywords: PropTypes.string
}

export default Seo

/*
 * Copyright (c) 2023, Salesforce, Inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 * TODO: Review this file and remove any constants that are not used.
 */

export const CUSTOM_HOME_TITLE = '🎉 Hello Zimmermann!';

// SFCC-83 — ZimmRecentlyViewedRail's client-side cap. Matches the Desktop Figma composition
// (`40000307:12444`, 5 bare product images across the rail's `group` child) — the Einstein
// recommender endpoint this rail's data ultimately comes from does not itself honour a requested
// `limit`, so the cap has to be enforced client-side, in the rail component itself, not assumed
// true of the input array.
export const RECENTLY_VIEWED_RAIL_MAX_ITEMS = 5;

// SFCC-83 — interim history-storage cap for `useRecentlyViewedHistory` (build plan §2, "Interim
// data source"). Set to 24, matching the Shopper Products `getProducts` endpoint's own hard
// per-request ID limit that `recentlyViewedProductFetch.ts` must cap to (confirmed directly in
// the SDK's own doc comment — see that file): storing more IDs than a single fetch can ever
// resolve would never produce a displayable card. NOTE — this overrides the build plan's own
// closed Open Question 17 (`= 500`, framed there as a pure engineering safety ceiling with no
// tie to a display cap) and has not been reconciled against B2's Full History page design, which
// the plan currently specifies as fetching the *full, uncapped* id list — flagged for Marcel to
// confirm, not silently resolved here.
export const RECENTLY_VIEWED_HISTORY_MAX_STORED = 24;

export {
  MAX_CACHE_AGE,
  STALE_WHILE_REVALIDATE,
  HOME_SHOP_PRODUCTS_CATEGORY_ID,
  HOME_SHOP_PRODUCTS_LIMIT,
} from '@salesforce/retail-react-app/app/constants';

export * from '@salesforce/retail-react-app/app/constants';

