3	 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given a `recommender` and
4	 * `useRecentlyViewedHistory`'s return value, does it render `ZimmRecentlyViewedRail`,
5	 * `ProductScroller`, or nothing at all. `ZimmRecentlyViewedRail`, `ProductScroller`,
6	 * `useRecentlyViewedHistory`, `useRecentlyViewedProductFetch`, and `selectRecentlyViewedCard` are
7	 * all mocked at the smallest surface — their own internals already have their own coverage
8	 * elsewhere (`zimmRecentlyViewedRail/index.test.tsx`, `useRecentlyViewedHistory.test.ts`,
9	 * `recentlyViewedProductFetch.test.ts`, `recentlyViewedCard.test.ts`; base `ProductScroller` is
10	 * untouched vendor code).
11	 *
12	 * **Revised 2026-09-08, build plan §2 "Interim data source"** — the Recently-Viewed branch no
13	 * longer reads `recommendations.recs` (Einstein's own response) at all; it reads
14	 * `recentlyViewedIds` off `useRecentlyViewedHistory` and real product data off
15	 * `useRecentlyViewedProductFetch` instead. Mocks and fixtures below were rewritten to match:
16	 * `useRecentlyViewedGate` is gone, and the Recently-Viewed-branch tests build their product
17	 * fixtures with a real `id` field (`ShopperProductsTypes.Product`'s own shape) instead of the old
18	 * Einstein-merged `productId`. The "any other recommender" test is otherwise unaffected — it still
19	 * feeds `ProductScroller` from a real Einstein-shaped `recommendations` object, since only the
20	 * Recently-Viewed branch's data source changed.
21	 */
22	import React from 'react';
23	import { describe, test, expect, vi, afterEach } from 'vitest';
24	import { render, screen } from '@testing-library/react';
25	import { ChakraProvider } from '@chakra-ui/react';
26	import { IntlProvider } from 'react-intl';
27	import { EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
28	import theme from 'app/theme';
29	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
30	import { useRecentlyViewedHistory } from '../../hooks/useRecentlyViewedHistory';
31	import { useRecentlyViewedProductFetch } from '../../utils/recentlyViewedProductFetch';
32	import { selectRecentlyViewedCard, type RecentlyViewedProduct } from '../../utils/recentlyViewedCard';
33	import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
34	import RecommendedProducts, { type RecommendedProductsProps } from '.';
35	
36	// Smallest-surface mocks throughout — see module docblock above for why each of these is safe to
37	// stub rather than exercise for real in this file.
38	
39	vi.mock('@salesforce/retail-react-app/app/hooks/use-einstein', () => ({
40	  default: vi.fn(),
41	}));
42	
43	vi.mock('@salesforce/retail-react-app/app/hooks/use-datacloud', () => ({
44	  default: () => ({ sendViewRecommendations: vi.fn() }),
45	}));
46	
47	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-customer', () => ({
48	  useCurrentCustomer: () => ({ data: { customerId: 'test-customer-id' } }),
49	}));
50	
51	// Real use-intersection-observer.js already degrades to `true` under jsdom (no global
52	// IntersectionObserver), but stubbed anyway per this step's own brief, for a deterministic
53	// `isOnScreen` this file doesn't otherwise need to reason about.
54	vi.mock('@salesforce/retail-react-app/app/hooks/use-intersection-observer', () => ({
55	  default: () => false,
56	}));
57	
58	vi.mock('@salesforce/retail-react-app/app/hooks/use-wish-list', () => ({
59	  useWishList: () => ({ data: undefined }),
60	}));
61	
62	vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
63	  useToast: () => vi.fn(),
64	}));
65	
66	vi.mock('@salesforce/retail-react-app/app/hooks/use-navigation', () => ({
67	  default: () => vi.fn(),
68	}));
69	
70	vi.mock('@salesforce/commerce-sdk-react', () => ({
71	  useShopperCustomersMutation: () => ({ mutateAsync: vi.fn() }),
72	}));
73	
74	// ProductScroller is a real `forwardRef` component (product-scroller/index.jsx) — mocked as one
75	// too, rather than a plain function, so `<ProductScroller ref={ref} .../>` doesn't trip React's
76	// "function components cannot be given refs" warning for no reason.
77	vi.mock('@salesforce/retail-react-app/app/components/product-scroller', () => ({
78	  default: React.forwardRef(function ProductScrollerStub(_props: unknown, ref: React.Ref<HTMLDivElement>) {
79	    return <div ref={ref} data-testid="product-scroller-stub" />;
80	  }),
81	}));
82	
83	// Relative paths matching index.tsx's own imports exactly — see overrideStyling.md's
84	// "Importing an already-overridden component" doctrine cited there.
85	vi.mock('../ui-kits/organisms/zimmRecentlyViewedRail', () => ({
86	  ZimmRecentlyViewedRail: vi.fn(() => <div data-testid="zimm-recently-viewed-rail-stub" />),
87	}));
88	
89	vi.mock('../../hooks/useRecentlyViewedHistory', () => ({
90	  useRecentlyViewedHistory: vi.fn(),
91	}));
92	
93	vi.mock('../../utils/recentlyViewedProductFetch', () => ({
94	  useRecentlyViewedProductFetch: vi.fn(),
95	}));
96	
97	vi.mock('../../utils/recentlyViewedCard', () => ({
98	  selectRecentlyViewedCard: vi.fn(),
99	}));
100	
101	const mockUseEinstein = vi.mocked(useEinstein);
102	const mockUseRecentlyViewedHistory = vi.mocked(useRecentlyViewedHistory);
103	const mockUseRecentlyViewedProductFetch = vi.mocked(useRecentlyViewedProductFetch);
104	const mockSelectRecentlyViewedCard = vi.mocked(selectRecentlyViewedCard);
105	const mockZimmRecentlyViewedRail = vi.mocked(ZimmRecentlyViewedRail);
106	
107	// Two products, deliberately different `id`s, so a mapping/filtering bug (wrong product picked,
108	// or the null-filter dropping the wrong entry) fails loudly rather than coincidentally matching —
109	// same doctrine recentlyViewedCard.test.ts documents as "G1". Shaped with a real `id` field
110	// (ShopperProductsTypes.Product's own shape), not the old Einstein-merged `productId`.
111	const mockRecentlyViewedProducts: RecentlyViewedProduct[] = [
112	  { id: 'rec-1', name: 'Product One' } as RecentlyViewedProduct,
113	  { id: 'rec-2', name: 'Product Two' } as RecentlyViewedProduct,
114	];
115	
116	// A real Einstein response shape — still used by the "any other recommender" test below, since
117	// only the Recently-Viewed branch's data source changed (build plan A6, 2026-09-08 revision).
118	const mockRecommendations = {
119	  recommenderName: 'might-also-like-einstein',
120	  recoUUID: 'test-reco-uuid',
121	  displayMessage: 'You Might Also Like',
122	  recs: [
123	    { productId: 'reco-1', name: 'Recommended One' },
124	    { productId: 'reco-2', name: 'Recommended Two' },
125	  ],
126	};
127	
128	const renderRecommendedProducts = (props: Partial<RecommendedProductsProps> = {}) =>
129	  render(
130	    <IntlProvider locale="en-AU" messages={{}}>
131	      <ChakraProvider theme={theme}>
132	        <RecommendedProducts recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE} {...props} />
133	      </ChakraProvider>
134	    </IntlProvider>,
135	  );
136	
137	afterEach(() => {
138	  vi.clearAllMocks();
139	});
140	
141	describe('RecommendedProducts — Recently Viewed branch (SFCC-83/84, build plan A6)', () => {
142	  test('recommender=PDP_RECENTLY_VIEWED + hasRecentlyViewed true renders ZimmRecentlyViewedRail, not ProductScroller', () => {
143	    // `recommendations` mirrors useEinstein()'s own real, untouched `useState([])` initial value
144	    // — the actual production state for this branch once bug fix #2 stops it from ever calling
145	    // getRecommendations/getZoneRecommendations (see index.tsx's own module docblock, point 2).
146	    mockUseEinstein.mockReturnValue({
147	      isLoading: false,
148	      recommendations: [],
149	      getZoneRecommendations: vi.fn(),
150	      getRecommendations: vi.fn(),
151	      sendClickReco: vi.fn(),
152	      sendViewReco: vi.fn(),
153	    });
154	    mockUseRecentlyViewedHistory.mockReturnValue({
155	      hasRecentlyViewed: true,
156	      recentlyViewedIds: ['rec-1', 'rec-2'],
157	      markProductViewed: vi.fn(),
158	    });
159	    mockUseRecentlyViewedProductFetch.mockReturnValue({
160	      products: mockRecentlyViewedProducts,
161	      isLoading: false,
162	    });
163	    // rec-2 deliberately maps to `null` (e.g. no usable image/name) — proves the branch's own
164	    // `.filter()` drops it instead of forwarding a null card or crashing.
165	    mockSelectRecentlyViewedCard.mockImplementation((product) =>
166	      product?.id === 'rec-2'
167	        ? null
168	        : {
169	            id: product?.id ?? '',
170	            href: `/product/${product?.id ?? ''}`,
171	            name: product?.name ?? '',
172	            primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
173	            currentPrice: undefined,
174	          },
175	    );
176	
177	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, title: 'Recently Viewed' });
178	
179	    expect(screen.getByTestId('zimm-recently-viewed-rail-stub')).toBeInTheDocument();
180	    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
181	
182	    // Branch's own mapping contract (not the rail's internals): the null-mapped product is
183	    // dropped, the surviving card carries the container-assigned `headingLevel`/`variation`, and
184	    // `title` is passed straight through from the caller's own prop — no `recommendations`
185	    // fallback, since `recommendations` is never populated for this branch (build plan A6, bug
186	    // fix #4).
187	    expect(mockZimmRecentlyViewedRail).toHaveBeenCalledTimes(1);
188	    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
189	    expect(railProps.title).toBe('Recently Viewed');
190	    expect(railProps.cards).toHaveLength(1);
191	    expect(railProps.cards[0]).toMatchObject({
192	      id: 'rec-1',
193	      headingLevel: 'h3',
194	      variation: 'recentlyViewed',
195	    });
196	
197	    // This branch is fed the real tracked ids, in the order the history hook returned them — the
198	    // "any other recommender" test below covers the mirror-image half (never handed real ids).
199	    expect(mockUseRecentlyViewedProductFetch).toHaveBeenCalledWith(['rec-1', 'rec-2']);
200	  });
201	
202	  test.each([
203	    ['hasRecentlyViewed true', true],
204	    ['hasRecentlyViewed false', false],
205	  ])(
206	    'any other recommender renders ProductScroller, not ZimmRecentlyViewedRail, regardless of history state (%s)',
207	    (_label, hasRecentlyViewedValue) => {
208	      mockUseEinstein.mockReturnValue({
209	        isLoading: false,
210	        recommendations: mockRecommendations,
211	        getZoneRecommendations: vi.fn(),
212	        getRecommendations: vi.fn(),
213	        sendClickReco: vi.fn(),
214	        sendViewReco: vi.fn(),
215	      });
216	      mockUseRecentlyViewedHistory.mockReturnValue({
217	        hasRecentlyViewed: hasRecentlyViewedValue,
218	        recentlyViewedIds: hasRecentlyViewedValue ? ['rec-1'] : [],
