229	      // A non-Recently-Viewed instance is never handed this shopper's real tracked ids (see
230	      // index.tsx's own `useRecentlyViewedProductFetch` call) — otherwise every other rail on the
231	      // same page would silently trigger its own redundant getProducts call for data it never
232	      // reads, even when real view history exists (the `hasRecentlyViewedValue` true case here).
233	      expect(mockUseRecentlyViewedProductFetch).toHaveBeenCalledWith([]);
234	    },
235	  );
236	
237	  test('recommender=PDP_RECENTLY_VIEWED + hasRecentlyViewed false renders null (AC 8): no rail, no scroller', () => {
238	    mockUseEinstein.mockReturnValue({
239	      isLoading: false,
240	      recommendations: [],
241	      getZoneRecommendations: vi.fn(),
242	      getRecommendations: vi.fn(),
243	      sendClickReco: vi.fn(),
244	      sendViewReco: vi.fn(),
245	    });
246	    mockUseRecentlyViewedHistory.mockReturnValue({
247	      hasRecentlyViewed: false,
