/**
 * SFCC-84, build plan section B1. Design source is provisional (Marcel's 2026-09-04 precedence
 * rule); the specific values this component's own behaviour depends on (the `plp` variation, the
 * item-count/title layout) were independently confirmed this session — see index.tsx's own module
 * docblock for the full citation. Nothing below re-derives or depends on the still-unconfirmed
 * geometry values (grid gaps, column counts) — those are `zimmRecentlyViewedGrid.css.ts`'s own
 * concern and are not exercised by anything in this file (jsdom + a mocked `useMultiStyleConfig`
 * cannot assert real computed CSS — see the "don't test that Chakra applies styles" exclusion in
 * .claude/rules/testing.md).
 *
 * Scoped per .claude/rules/testing.md: this component's OWN contract only — order preservation,
 * empty-input renders null, and that `itemCountLabel` is rendered verbatim (never recomputed from
 * `cards.length` internally). `ZimmProductCard`'s own internals (badge rendering, hover-swap,
 * bag/size-chip/price composition under `variation: 'plp'`, accessible-name concatenation, etc.)
 * are already covered by zimmProductCard/index.test.tsx and are deliberately NOT re-tested here —
 * testing.md's "no duplicate coverage across layers". Unlike `ZimmRecentlyViewedRail`, this
 * component enforces no display cap of its own, so there is no cap-describe block to mirror here
 * — see index.tsx's own `cards` JSDoc for why capping is the caller's job.
 *
 * `ZimmProductCard` is composed for real here (not mocked out) — same "costs nothing, gives real
 * integration confidence" precedent zimmRecentlyViewedRail/index.test.tsx documents for itself.
 * Its own `data-testid="product-card"` / `data-product-id` DOM hooks
 * (zimmProductCard/index.tsx's own docblock: "a DOM hook for QA automation/analytics") are what
 * this file's order assertions read.
 *
 * Fixtures use `variation: 'plp'` — this grid's own confirmed variation (index.tsx's own `cards`
 * JSDoc) — deliberately minimal (no `currentPrice`/`badge`/`sizeChipValues`/`onAddToBag`): unlike
 * `recentlyViewed` (image-only), `plp` always mounts `ZimmProductCardContent` in full
 * (`showContent: true` unconditionally per `zimmProductCard/index.tsx`'s `VARIATION_CONFIG`), so
 * the composed tree here is deeper than the rail's own. Keeping fixtures to only the required base
 * fields keeps that tree's actually-exercised render paths minimal (e.g. `ZimmProductPrice`
 * "renders nothing when there is no price" per its own docblock, and no `ZimmSizeChip` instances
 * mount when `sizeChipValues` is omitted) without weakening this file's own assertions, which
 * never depend on those optional fields anyway.
 *
 * `useMultiStyleConfig` is mocked with one flat object covering every part every composed
 * descendant reads for a `plp`-variation render — this recipe's own 3 parts, plus
 * `ZimmProductCard`'s `root`, `ZimmProductCardMedia`'s 12 parts, `ZimmProductCardContent`'s 11
 * parts (mounted here, unlike the rail's own `recentlyViewed` test — `showContent` is `true` for
 * `plp`), `ZimmProductPrice`'s 3 parts (always mounted when Content mounts, regardless of whether
 * a price value is actually supplied), and `ZimmSizeChipGroup`/`ZimmSizeChip`'s parts (mounted
 * whenever `showSizeChips` is true, i.e. unconditionally for `plp`, regardless of whether
 * `sizeChipValues` is supplied — see `zimmProductCardContent/index.tsx`'s own
 * `sizeChipValues ?? []` fallback). Same "neither test setup nor Chakra cares which recipe name
 * asked for it" precedent `zimmRecentlyViewedRail/index.test.tsx` documents — parts from
 * different recipes share this one flat object with no namespacing, including where two
 * unrelated recipes happen to both declare a `container` part (this recipe and
 * `ZimmProductPrice` both do); harmless here since nothing in this file asserts real computed
 * style values, only presence/rendering. This list was independently verified against each
 * recipe's own `parts:` array (not copied from `zimmRecentlyViewedRail/index.test.tsx`'s own
 * Media list, which omits Media's own `root` part — confirmed by direct inspection of
 * `zimmProductCardMedia.css.ts` to be a real, declared, but here-included part).
 *
 * The icon-module mocks below are the same known Vitest SVG-import issue documented in
 * .claude/rules/testing.md ("Known gap: ZimmIcon throws under Vitest") and already mocked in
 * zimmProductCard/index.test.tsx and zimmRecentlyViewedRail/index.test.tsx — copied verbatim
 * since this file sits at the identical ui-kits/organisms/<name>/ depth, so the same relative
 * specifiers resolve to the same modules. `ZimmIcon` is genuinely rendered here (unlike the
 * rail's own recentlyViewed-variation test, where it is statically imported but never mounted):
 * `plp`'s bag button renders `<ZimmIcon type="bag" aria-hidden />` (zimmProductCardContent/
 * index.tsx).
 *
 * No `react-router-dom` mock (same reasoning as `zimmRecentlyViewedRail/index.test.tsx`) — this
 * component never calls `useHistory`/renders a `Link` itself; `ZimmProductCard`'s own click-
 * passthrough and `ZimmProductCardContent`'s own name-link are already covered by their own test
 * files, not re-proven here. `MemoryRouter` is still required as ambient context, since both are
 * mounted for real.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { ZimmRecentlyViewedGrid } from './index';
import type { ZimmProductCardProps } from '../zimmProductCard';

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({
      // ZimmRecentlyViewedGrid (this component's own recipe).
      container: {},
      header: {},
      grid: {},
      // ZimmProductCard.
      root: {},
      // ZimmProductCardMedia (verified against zimmProductCardMedia.css.ts's own `parts` array —
      // includes `root`, unlike zimmRecentlyViewedRail/index.test.tsx's own mock for the same
      // recipe).
      scrollContainer: {},
      slide: {},
      image: {},
      hoverSwapBase: {},
      hoverSwapOverlay: {},
      badge: {},
      badgeLabel: {},
      close: {},
      carousel: {},
      arrowButton: {},
      indicatorWrapper: {},
      // ZimmProductCardContent (mounted here — `plp`'s `showContent` is always `true`).
      nameRow: {},
      nameLink: {},
      bagWrapper: {},
      bagButton: {},
      attributesRow: {},
      colourText: {},
      sizeText: {},
      priceWrapper: {},
      sizeChipWrapper: {},
      notifyMeButton: {},
      // ZimmProductPrice — always mounted inside Content regardless of whether a price value is
      // actually supplied (it renders nothing itself in that case, but still calls the hook).
      wasPrice: {},
